result:
**The bug:** The condition `decoded.exp < Date.now() / 1000` uses strict less-than, so a token where `exp === currentTime` passes the check and is accepted. Fix is `<=`. However, there's a deeper issue: `jwt.verify()` already handles expiry and will throw `TokenExpiredError` — the manual check is redundant and error-prone. The right approach is to remove the manual check and handle the error types properly.

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  if (!process.env.JWT_SECRET) {
    return res.status(500).json({ error: 'Server misconfiguration' });
  }

  try {
    // jwt.verify() rejects tokens where exp <= currentTime (handles the boundary correctly)
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    if (err.name === 'JsonWebTokenError') {
      return res.status(401).json({ error: 'Invalid token' });
    }
    if (err.name === 'NotBeforeError') {
      return res.status(401).json({ error: 'Token not yet valid' });
    }
    // Unexpected error — don't leak details
    return res.status(500).json({ error: 'Authentication error' });
  }
}

module.exports = authMiddleware;
```

**What changed and why:**

| Issue | Before | After |
|---|---|---|
| Boundary bug | `exp < now` accepts tokens expiring exactly now | Removed — `jwt.verify()` uses `exp <= now` internally, correctly rejecting boundary tokens |
| Redundant check | Manual expiry check after `jwt.verify()` creates a logic gap | Deleted; rely on the library's correct implementation |
| Missing secret guard | `undefined` secret silently accepts any token signed with `undefined` | Explicit 500 if `JWT_SECRET` is unset |
| Error detail | All JWT errors collapsed to one message | `TokenExpiredError`, `JsonWebTokenError`, `NotBeforeError` handled separately; unexpected errors return 500 without leaking stack traces |
